// Adaptación de las clases Pedido y ValidadorCobertura para n8n
class Pedido {
  constructor({ id, cliente, monto, ip }) {
    this.id = id;
    this.cliente = cliente;
    this.monto = Number(monto);
    this.ip = ip;
    this.costoEnvio = 0;
    this.aprobado = false;
    this.motivoRechazo = null;
  }
  aplicarCostoEnvio(c) { this.costoEnvio = Number(c); }
  obtenerTotal() { return this.monto + this.costoEnvio; }
  aprobar() { this.aprobado = true; }
  rechazar(m) { this.aprobado = false; this.motivoRechazo = m; }
  toJSON() {
    return {
      id: this.id,
      cliente: this.cliente,
      monto: this.monto,
      costoEnvio: this.costoEnvio,
      total: this.obtenerTotal(),
      ip: this.ip,
      aprobado: this.aprobado,
      motivoRechazo: this.motivoRechazo
    };
  }
}

class ValidadorCobertura {
  constructor(tarifas = { GT: 25.0, SV: 35.0, HN: 40.0 }) {
    this.tarifas = tarifas;
  }
  verificarZona(geo) {
    if (!geo || geo.status !== 'success') {
      return { cubierto: false, motivo: geo?.error || geo?.message || 'Falla al contactar servicio de geolocalización (API caída/timeout)' };
    }
    if (!this.tarifas[geo.countryCode]) {
      return { cubierto: false, motivo: `Zona fuera de cobertura (${geo.country || 'Desconocido'})` };
    }
    return { cubierto: true, pais: geo.countryCode, ciudad: geo.city };
  }
  calcularCosto(geo, monto) {
    return monto >= 500 ? 0.0 : this.tarifas[geo.countryCode];
  }
}

// Obtención de datos del Webhook e IP-API
const rawOrder = $('Webhook Trigger').first().json.body;
const geoResponse = $input.first().json;

const validador = new ValidadorCobertura();
const pedido = new Pedido(rawOrder);

// Manejo de Error 2: Falla de red o respuesta vacía de IP-API
if (geoResponse.error || !geoResponse.status) {
  pedido.rechazar('Error de conexión con IP-API externa');
  return [{ json: { ...pedido.toJSON(), coberturaValida: false } }];
}

const zona = validador.verificarZona(geoResponse);
if (!zona.cubierto) {
  pedido.rechazar(zona.motivo);
  return [{ json: { ...pedido.toJSON(), coberturaValida: false } }];
}

const costoEnvio = validador.calcularCosto(geoResponse, pedido.monto);
pedido.aplicarCostoEnvio(costoEnvio);
pedido.aprobar();

return [{
  json: {
    ...pedido.toJSON(),
    coberturaValida: true,
    ubicacion: { pais: zona.pais, ciudad: zona.ciudad }
  }
}];
